fn turn_rest(rows: List[List[Int]], cols: Int) -> List[List[Int]] {
  let col_indexes = range(0, cols)
  let columns = col_indexes.map(fn(c) => rows.map(fn(r) => r.get_or(c, 0)))
  return columns.reverse()
}

pub fn spiral(m: List[List[Int]]) -> List[Int] {
  let empty_row: List[Int] = []
  let head = m.first().unwrap_or(empty_row)
  let rest = m.drop(1)
  let cols = head.len()
  if rest.is_empty() or cols == 0 {
    return head
  }
  let next = turn_rest(rows: rest, cols: cols)
  return head.concat(spiral(next))
}
